$t['The commit identifies the Git revision checked out on this server; local file edits are not included. A Git tag is shown when one points directly to that commit.'] = 'کامیت، نسخه Git بررسی‌شده روی این سرور را مشخص می‌کند؛ ویرایش‌های محلی فایل‌ها شامل نمی‌شوند. اگر یک تگ Git مستقیماً به آن کامیت اشاره کند، نمایش داده می‌شود.';
$t['The Companion Chat service is not available right now. Ask your site administrator to check the AI plugin connection.'] = 'سرویس Companion Chat در حال حاضر در دسترس نیست. از مدیر سایت بخواهید اتصال افزونه هوش مصنوعی را بررسی کند.';
$t['The connection to the destination was dropped mid-stream. This may be a temporary network issue; FFMPEG will try to reconnect.'] = 'اتصال به مقصد در میانه پخش قطع شد. ممکن است مشکل موقت شبکه باشد؛ FFMPEG تلاش می‌کند دوباره متصل شود.';
$t['The converted files were kept. Contact the site administrator to retry the transfer; you do not need to upload the video again.'] = 'فایل‌های تبدیل‌شده نگه داشته شدند. برای تلاش مجدد انتقال با مدیر سایت تماس بگیرید؛ نیازی به آپلود دوباره ویدیو نیست.';
$t['The converted video could not be sent back to this site.'] = 'ویدیوی تبدیل‌شده را نمی‌توان به این سایت بازگرداند.';
$t['The customers of the selected card. Search, sort, copy the e-mails or export everything to a spreadsheet.'] = 'مشتریان کارت انتخاب‌شده. جستجو، مرتب‌سازی، کپی ایمیل‌ها یا خروجی گرفتن همه موارد در صفحه‌گسترده.';
$t['The database version changes only when a database migration is applied. It is not expected to match the release tag or commit.'] = 'نسخه پایگاه داده فقط هنگام اعمال مهاجرت پایگاه داده تغییر می‌کند. انتظار نمی‌رود با تگ انتشار یا کامیت مطابقت داشته باشد.';
$t['The default'] = 'پیش‌فرض';
$t['The destination RTMP server refused the connection. Check the stream URL and make sure the server is online.'] = 'سرور RTMP مقصد اتصال را رد کرد. URL پخش را بررسی کنید و مطمئن شوید سرور آنلاین است.';
$t['The destination server requires authentication. Check the stream key.'] = 'سرور مقصد نیاز به احراز هویت دارد. کلید پخش را بررسی کنید.';
$t['The destination server returned 403. The stream key may be invalid or expired.'] = 'سرور مقصد خطای 403 برگرداند. ممکن است کلید پخش نامعتبر یا منقضی شده باشد.';
$t['The destination video was removed or this account cannot edit it. Check the video and account access on the site.'] = 'ویدیوی مقصد حذف شده یا این حساب اجازه ویرایش آن را ندارد. دسترسی ویدیو و حساب را در سایت بررسی کنید.';
$t['The download is controlled by the system, there is nothing to check on the user'] = 'دریافت توسط سیستم کنترل می‌شود و چیزی دربارهٔ کاربر برای بررسی وجود ندارد';
$t['The download permission is site wide, so there is nothing to check on the video'] = 'مجوز دانلود برای کل سایت است، بنابراین چیزی برای بررسی روی ویدیو وجود ندارد';
$t['The download permission is site wide, so there is nothing to check onthe video'] = 'مجوز دریافت در سراسر سایت اعمال می‌شود؛ بنابراین چیزی برای بررسی دربارهٔ ویدئو وجود ندارد';
$t['The email is invalid'] = 'ایمیل نامعتبر است';
$t['The encoder could not download the original file.'] = 'رمزگذار نتوانست فایل اصلی را دانلود کند.';
$t['The encoder could not find this video on the site.'] = 'رمزگذار نتوانست این ویدیو را در سایت پیدا کند.';
$t['The encoder did not confirm that the video was added to the queue. Please retry.'] = 'رمزگذار افزوده شدن ویدیو به صف را تأیید نکرد. لطفاً دوباره تلاش کنید.';
$t['The encoder is running out of disk space'] = 'فضای دیسک رمزگذار در حال اتمام است';
$t['The encoder reported an unexpected error.'] = 'رمزگذار خطای غیرمنتظره‌ای گزارش داد.';
$t['The encoding process stopped unexpectedly, and the automatic retries also failed.'] = 'فرایند رمزگذاری به‌طور غیرمنتظره متوقف شد و تلاش‌های خودکار مجدد نیز ناموفق بودند.';
$t['The encoding queue is stalled'] = 'صف رمزگذاری متوقف شده است';
$t['The file could not be converted. It may be damaged or use a format the encoder does not support.'] = 'فایل قابل تبدیل نبود. ممکن است آسیب دیده باشد یا از قالبی استفاده کند که رمزگذار پشتیبانی نمی‌کند.';
$t['The file must be an .vtt file!'] = 'فایل باید از نوع .vtt باشد!';
$t['The file must be an .vtt or .srt file!'] = 'فایل باید از نوع .vtt یا .srt باشد!';
$t['The final charge uses the duration measured during processing. A connected Marketplace wallet is required.'] = 'هزینه نهایی بر اساس مدت زمان اندازه‌گیری‌شده در حین پردازش محاسبه می‌شود. یک کیف پول Marketplace متصل لازم است.';
$t['The following movie contains materials that are not suitable for children 17 and under.'] = 'فیلم زیر حاوی مطالبی است که برای کودکان ۱۷ سال و کمتر مناسب نیست.';
$t['The following movie contains materials that may not be suitable for children 17 and under.'] = 'فیلم زیر حاوی مطالبی است که ممکن است برای کودکان ۱۷ سال و کمتر مناسب نباشد.';
$t['The form to signup will not exists'] = 'فرم ثبت‌نام وجود نخواهد داشت';
$t['The gift code has been canceled. If this is unexpected, please contact our support team.'] = 'کد هدیه لغو شده است. اگر این غیرمنتظره است، لطفاً با تیم پشتیبانی ما تماس بگیرید.';
$t['The gift code is currently inactive. Please check back later or contact support.'] = 'کد هدیه در حال حاضر غیرفعال است. لطفاً بعداً دوباره بررسی کنید یا با پشتیبانی تماس بگیرید.';
$t['The information above corresponds to our official records and confirms the authenticity of this certificate.'] = 'اطلاعات بالا با سوابق رسمی ما مطابقت دارد و اصالت این گواهی را تأیید می‌کند.';
$t['The input stream contains invalid data. The source HLS may not be ready yet or the stream was interrupted.'] = 'جریان ورودی حاوی داده‌های نامعتبر است. ممکن است HLS منبع هنوز آماده نباشد یا جریان قطع شده باشد.';
$t['The installed PHP package lists both fixes, but this web process still runs the copy loaded before the update. Restart Apache or PHP-FPM.'] = 'بسته PHP نصب‌شده هر دو اصلاح را فهرست کرده است، اما این فرایند وب هنوز نسخه‌ای را اجرا می‌کند که پیش از به‌روزرسانی بارگذاری شده بود. Apache یا PHP-FPM را دوباره راه‌اندازی کنید.';
$t['Their last plans add up to %s'] = 'مجموع آخرین طرح‌های آن‌ها %s است';
