$t['The Permissions Plugin is not installed. Please install it if you want to customize the permissions.'] = 'افزونهٔ مجوزها نصب نشده است. اگر می‌خواهید مجوزها را سفارشی کنید، آن را نصب کنید.';
$t['The plugin is disabled'] = 'افزونه غیرفعال است';
$t['The program is empty'] = 'برنامه خالی است';
$t['There\'s an unknown status associated with this gift code. Please contact support for assistance.'] = 'وضعیت نامشخصی به این کد هدیه مرتبط است. لطفاً برای دریافت کمک با پشتیبانی تماس بگیرید.';
$t['There, you can set'] = 'در آنجا می‌توانید تنظیم کنید';
$t['There are no notifications'] = 'هیچ اعلانی وجود ندارد';
$t['There are various kinds of media you can integrate here. They are working different'] = 'انواع مختلفی از رسانه‌ها را می‌توانید در اینجا یکپارچه کنید. عملکرد آن‌ها با یکدیگر متفاوت است';
$t['The recover pass does not match!'] = 'رمز بازیابی مطابقت ندارد!';
$t['The regular form to signin will not exist, if you check this will only have social login or LDAP option'] = 'اگر این گزینه را فعال کنید، فرم معمول ورود وجود نخواهد داشت و فقط امکان ورود از طریق شبکه‌های اجتماعی یا LDAP فراهم می‌شود';
$t['There is missing data to recover your password'] = 'داده‌های لازم برای بازیابی گذرواژه وجود ندارد';
$t['There is no streaming now'] = 'اکنون هیچ پخش زنده‌ای در جریان نیست';
$t['The release number and the AVideo database version are independent. Code update status is determined by commit history.'] = 'شماره نسخه انتشار و نسخه پایگاه داده AVideo مستقل از هم هستند. وضعیت به‌روزرسانی کد بر اساس تاریخچه commitها تعیین می‌شود.';
$t['The restreamer server cannot reach the destination. Check network connectivity.'] = 'سرور restreamer نمی‌تواند به مقصد دسترسی پیدا کند. اتصال شبکه را بررسی کنید.';
$t['The same alert is repeated at most every %s while the problem continues.'] = 'تا زمانی که مشکل ادامه دارد، همان هشدار حداکثر هر %s یک بار تکرار می‌شود.';
$t['The same alert is repeated at most every few hours while the problem continues.'] = 'تا زمانی که مشکل ادامه دارد، همان هشدار حداکثر هر چند ساعت یک بار تکرار می‌شود.';
$t['The selected camera or microphone is not available. Please choose another device.'] = 'دوربین یا میکروفون انتخاب‌شده در دسترس نیست. لطفاً دستگاه دیگری انتخاب کنید.';
$t['The site is currently offline due to a database issue. We are working to resolve the problem as quickly as possible.'] = 'سایت در حال حاضر به دلیل مشکل پایگاه داده آفلاین است. ما در تلاشیم تا مشکل را در سریع‌ترین زمان ممکن برطرف کنیم.';
$t['The site is temporarily unavailable because the server\'s disk is full. We are working on this issue and will be back shortly.'] = 'سایت به دلیل پر شدن دیسک سرور موقتاً در دسترس نیست. ما در حال رسیدگی به این مشکل هستیم و به‌زودی بازمی‌گردیم.';
$t['The site is undergoing maintenance as the server\'s disk is nearing capacity. We are addressing the issue and will be back shortly.'] = 'سایت به دلیل نزدیک شدن دیسک سرور به ظرفیت کامل در حال تعمیر و نگهداری است. ما در حال رسیدگی به مشکل هستیم و به‌زودی بازمی‌گردیم.';
$t['The site refused access. Renew the encoder account access and check its upload permissions.'] = 'سایت دسترسی را رد کرد. دسترسی حساب encoder را تمدید کرده و مجوزهای آپلود آن را بررسی کنید.';
$t['The site will display only a login form to un authenticated users'] = 'سایت فقط فرم ورود را به کاربرانی نمایش می‌دهد که احراز هویت نشده‌اند';
$t['The source stream ended. If the live was stopped intentionally this is normal.'] = 'جریان منبع به پایان رسید. اگر پخش زنده عمداً متوقف شده باشد، این طبیعی است.';
$t['The stream has timestamp discontinuities. This can cause buffering or playback issues on the destination platform.'] = 'جریان دارای ناپیوستگی در مهر زمانی است. این می‌تواند باعث بافر شدن یا مشکلات پخش در پلتفرم مقصد شود.';
